function countEvenStretches(nums: number[]): number {
  let total = 0;
  for (let i = 0; i + 2 < nums.length; i++) {
    const step = nums[i + 1] - nums[i];
    for (let j = i + 2; j < nums.length && nums[j] - nums[j - 1] === step; j++) total++;
  }
  return total;
}

