class Solution:
    def countEvenStretches(self, nums: List[int]) -> int:
        total = 0
        for i in range(len(nums) - 2):
            step = nums[i + 1] - nums[i]
            j = i + 2
            while j < len(nums) and nums[j] - nums[j - 1] == step:
                total += 1
                j += 1
        return total

