function countEvenStretches(nums: number[]): number {
  let cur = 0, total = 0;
  for (let i = 2; i < nums.length; i++) {
    if (nums[i] - nums[i - 1] === nums[i - 1] - nums[i - 2]) cur++;
    else cur = 0;
    total += cur;
  }
  return total;
}

